def choose_move(observation):
    x, y = observation['self_position']
    width, height = observation['grid_width'], observation['grid_height']
    resources = set(observation['resources'])
    obstacles = set(observation['obstacles'])
    opponent_x, opponent_y = observation['opponent_position']
    moves = {'up': (0, -1), 'down': (0, 1), 'left': (-1, 0), 'right': (1, 0)}
    def safe(nx, ny):
        return 0 <= nx < width and 0 <= ny < height and (nx, ny) not in obstacles
    # Prefer move towards resource if adjacent
    for name, (dx, dy) in moves.items():
        nx, ny = x + dx, y + dy
        if safe(nx, ny):
            if (nx, ny) in resources:
                return [dx, dy]
    # Else, move away from opponent if possible
    for name, (dx, dy) in moves.items():
        nx, ny = x + dx, y + dy
        if safe(nx, ny):
            dist_current = abs(x - opponent_x) + abs(y - opponent_y)
            dist_new = abs(nx - opponent_x) + abs(ny - opponent_y)
            if dist_new > dist_current:
                return [dx, dy]
    # Else, stay still
    return [0, 0]
